mapper.select:
SELECT diag.*,
       co.order_no,
       patient.real_name AS patient_name,
       doctor.real_name AS doctor_name
FROM diagnosis diag
LEFT JOIN check_order co ON diag.order_id = co.id
LEFT JOIN sys_user patient ON diag.patient_id = patient.id
LEFT JOIN sys_user doctor ON diag.doctor_id = doctor.id
WHERE diag.deleted = 0

    AND diag.order_id = #{query.orderId}


    AND diag.patient_id = #{query.patientId}


    AND diag.doctor_id = #{query.doctorId}


    AND diag.risk_level = #{query.riskLevel}


    AND diag.status = #{query.status}

ORDER BY diag.create_time DESC
